/// <summary>
/// The service class for sales order cancel process.
/// </summary>
class METPickListService extends SysOperationServiceBase
{
    #OCCRetryCount

}

Method.Source:
/// <summary>
/// Instantiate new METPickListService object
/// </summary>
/// <returns>New object</returns>
public static METPickListService contruct()
{
    return new METPickListService();
}

    /// <summary>
    /// cancels the sales order.
    /// </summary>
    /// <param name="pickListRequest">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METPickListCancelResponseContract</c>
    /// </returns>
    public METPickListResponseContract cancelPickList(METPickListRequestContract pickListRequest)
    {
        METProcessingStatus result;
        Description255      message = "@MET:NoRecordsUpdated";

        [result, message] = this.processCancelPickList(pickListRequest);
        
        return METPickListResponseContract::newFromParameters(result, message);
    }

    /// <summary>
    /// cancels the pick list
    /// </summary>
    /// <param name="_pickListRequest">The contract instance</param>
    /// <returns>Container of results</returns>
    public container processCancelPickList(METPickListRequestContract _pickListRequest)
    {
        METProcessingStatus result;
        Description255      message;

        DataAreaId          dataAreaId;
        WMSPickingRouteID   pickingRouteId;
        WMSPickingRoute     pickingRoute;

        dataAreaId  = _pickListRequest.parmDataAreaId();
        pickingRouteId = _pickListRequest.parmPickingRouteId();

        try
        {
            ttsbegin;

            changecompany(dataAreaId)
            {
                pickingRoute = WMSPickingRoute::find(pickingRouteId, true);
        
                if(!pickingRoute.RecId)
                {
                    result = METProcessingStatus::Error;
                    message = "@MET:PickListNotFound";
                }
                else if(!pickingRoute.canBeCancelled())
                {
                    result = METProcessingStatus::Error;
                    message = "@MET:PickListNotActive";
                }
                else
                {
                    pickingRoute.cancel();
                    
                    result = METProcessingStatus::Success;
                    message = "@MET:PickListUpdateSuccessful";
                }

                if(result == METProcessingStatus::Error)
                {
                    throw error(message);
                }

                ttscommit;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:PickListUpdateFailedDatabaseDeadlockOccurred");
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:PickListUpdateFailedDatabaseDeadlockOccurred");
                throw Exception::Deadlock;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:PickListUpdateFailedDatabaseConflictOccurred");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:PickListUpdateFailedDatabaseConflictOccurred");
                throw Exception::UpdateConflict;
            }
        }

        return [result, message];
    }
